/*
=====================================================
KODE FUNGSI OTAK UTAMA (SELISIH VOLUME + MANUAL RESET)
=====================================================
*/

// --- KONFIGURASI ---
const LEVEL_EMPTY = 10;     // Mulai isi jika > 30cm (jarak sensor)
const LEVEL_FULL = 5;      // Stop isi jika < 10cm
const GRACE_PERIOD = 5000;  // Masa tenggang 5 detik

// Konfigurasi Kebocoran (Metode Selisih Volume)
const MAX_DIFF_LIMIT = 0.75;  // BATAS AMAN: Maksimal selisih 1.0 Liter
const MIN_VOLUME_CHECK = 0.5; // Mulai cek setelah 0.5 Liter air lewat
// -------------------

// Variabel Memori
let state = flow.get("system_state") || "IDLE";
let manualLock = flow.get("manual_lock") || false;

// Pesan Output Default
let valveMsg = null;
let lockMsg = null;
let statusMsg = { payload: state };

// === BAGIAN 1: INPUT DARI TOMBOL MANUAL ===
if (typeof msg.payload === 'boolean' || msg.payload === "true" || msg.payload === "false") {
    manualLock = (msg.payload === "true" || msg.payload === true);
    flow.set("manual_lock", manualLock);

    if (manualLock) {
        state = "LOCKED";
        valveMsg = { payload: "CLOSE" };
        lockMsg = { payload: "true" };
        statusMsg.payload = "Sistem Dikunci Manual (Valve Mati).";
    } else {
        state = "IDLE";
        lockMsg = { payload: "false" };
        statusMsg.payload = "Manual Lock Dibuka. Menunggu sensor...";
    }
    flow.set("system_state", state);

// === BAGIAN 2: INPUT DARI SENSOR ESP32 ===
} else if (msg.payload && typeof msg.payload === 'object') {
    let data = msg.payload;
    let level = data.level_cm;
    let vol1 = data.total_volume1_l || 0;
    let vol2 = data.total_volume2_l || 0;
    let sensorValid = (level > 0);

    if (manualLock) {
        statusMsg.payload = "Sistem Dikunci Manual.";
        return [null, null, statusMsg];
    }

    switch (state) {
        case "IDLE":
            statusMsg.payload = "Standby (Level: " + level + "cm)";
            if (sensorValid && level > LEVEL_EMPTY) {
                valveMsg = { payload: "OPEN" };
                statusMsg.payload = "Air Kurang! Memulai Pengisian...";
                flow.set("system_state", "PRIMING");

                setTimeout(() => {
                    if (flow.get("system_state") === "PRIMING") {
                        flow.set("system_state", "MONITORING");
                    }
                }, GRACE_PERIOD);
            }
            break;

        case "PRIMING":
            statusMsg.payload = "Masa Tenggang (Mengisi...)";
            if (sensorValid && level < LEVEL_FULL) {
                valveMsg = { payload: "CLOSE" };
                statusMsg.payload = "Penuh. Selesai.";
                flow.set("system_state", "IDLE");
            }
            break;

        case "MONITORING":
            // --- LOGIKA BARU: HITUNG SELISIH ---
            // Menghitung berapa liter air yang hilang di jalan
            // Rumus: Input (Vol1) - Output (Vol2)
            let selisih = vol1 - vol2; 

            statusMsg.payload = `Mengisi... (Selisih: ${selisih.toFixed(2)} L)`;

            // Cek Kebocoran (Hanya jika volume > 0.5L agar pembacaan stabil)
            if (vol1 > MIN_VOLUME_CHECK) {
                // Jika selisih melebihi batas aman (misal > 1 Liter)
                if (selisih > MAX_DIFF_LIMIT) {
                    statusMsg.payload = `BAHAYA: Bocor! Selisih ${selisih.toFixed(2)}L melebihi batas ${MAX_DIFF_LIMIT}L`;

                    valveMsg = { payload: "CLOSE" };
                    lockMsg = { payload: "true" };
                    state = "LOCKED";
                    flow.set("system_state", state);
                    flow.set("manual_lock", true);
                }
            }

            // Cek Penuh Normal
            if (sensorValid && level < LEVEL_FULL) {
                valveMsg = { payload: "CLOSE" };
                statusMsg.payload = "Tangki Penuh. Pengisian Selesai.";
                flow.set("system_state", "IDLE");
            }
            break;

        case "LOCKED":
            statusMsg.payload = "TERKUNCI. Reset tombol untuk mulai.";
            break;
    }
}

return [valveMsg, lockMsg, statusMsg];
